### Python

```python
import sys


def solve_case(n, m, arr):
    # bucket[x] 存储所有值为 x 的元素下标（从小到大）
    buckets = [[] for _ in range(n + 1)]

    # 按原下标顺序放入桶中
    for i in range(n):
        buckets[arr[i]].append(i)

    # removed[i] 表示原数组下标 i 的元素是否被删除
    removed = [False] * n

    # 按值从小到大删除
    for value in range(1, n + 1):
        if m == 0:
            break

        size = len(buckets[value])

        # 如果当前值的所有元素都要被删除
        if size <= m:
            for idx in buckets[value]:
                removed[idx] = True
            m -= size
        else:
            # 只删除当前值中下标最小的前 m 个
            for i in range(m):
                removed[buckets[value][i]] = True
            m = 0
            break

    # 按原顺序收集未删除元素
    ans = []
    for i in range(n):
        if not removed[i]:
            ans.append(str(arr[i]))

    return " ".join(ans)


def main():
    input = sys.stdin.readline
    t = int(input().strip())
    res = []

    for _ in range(t):
        n, m = map(int, input().split())
        arr = list(map(int, input().split()))
        res.append(solve_case(n, m, arr))

    sys.stdout.write("\n".join(res))


if __name__ == "__main__":
    main()
```

