import java.io.BufferedReader;
import java.io.InputStreamReader;
import java.io.IOException;
import java.util.ArrayList;
import java.util.List;
import java.util.StringTokenizer;

public class Main {

    // 处理一组测试数据，返回最终序列
    public static String solveCase(int n, int m, int[] arr) {
        // buckets[x] 存储所有值为 x 的元素下标（从小到大）
        List<Integer>[] buckets = new ArrayList[n + 1];
        for (int i = 1; i <= n; i++) {
            buckets[i] = new ArrayList<>();
        }

        // 按原下标顺序放入桶中
        for (int i = 0; i < n; i++) {
            buckets[arr[i]].add(i);
        }

        // removed[i] 表示原数组下标 i 的元素是否被删除
        boolean[] removed = new boolean[n];

        // 按值从小到大删除
        for (int value = 1; value <= n && m > 0; value++) {
            int size = buckets[value].size();

            // 如果当前值的所有元素都要被删除
            if (size <= m) {
                for (int idx : buckets[value]) {
                    removed[idx] = true;
                }
                m -= size;
            } else {
                // 只删除当前值中下标最小的前 m 个
                for (int i = 0; i < m; i++) {
                    removed[buckets[value].get(i)] = true;
                }
                m = 0;
                break;
            }
        }

        // 按原顺序收集未删除元素
        StringBuilder sb = new StringBuilder();
        boolean first = true;
        for (int i = 0; i < n; i++) {
            if (!removed[i]) {
                if (!first) {
                    sb.append(' ');
                }
                sb.append(arr[i]);
                first = false;
            }
        }

        return sb.toString();
    }

    public static void main(String[] args) throws Exception {
        BufferedReader br = new BufferedReader(new InputStreamReader(System.in));
        StringBuilder out = new StringBuilder();

        int t = Integer.parseInt(br.readLine().trim());

        for (int caseIndex = 0; caseIndex < t; caseIndex++) {
            StringTokenizer st = new StringTokenizer(br.readLine());
            int n = Integer.parseInt(st.nextToken());
            int m = Integer.parseInt(st.nextToken());

            int[] arr = new int[n];
            st = new StringTokenizer(br.readLine());
            for (int i = 0; i < n; i++) {
                arr[i] = Integer.parseInt(st.nextToken());
            }

            out.append(solveCase(n, m, arr));
            if (caseIndex != t - 1) {
                out.append('\n');
            }
        }

        System.out.print(out.toString());
    }
}
